SELECT ?point ?ts_id WHERE {
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts_id .
  FILTER(str(?point) LIKE "%AHU01%" || str(?point) LIKE "%AHU02%" || str(?point) LIKE "%AHU03%")
}

SELECT ?point ?ts_id WHERE {
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts_id .
  FILTER ( strcontains(str(?point), "AHU01") || strcontains(str(?point), "AHU02") || strcontains(str(?point), "AHU03") )
}

